"""Textes des fiches App Store dans toutes les langues (Foldly, Origamo, Waffle Fold).

`python3 tools/meta/build_meta.py` écrit tools/meta/foldly.json, origamo.json et waffle.json.
Pour Foldly et Origamo, les 7 langues déjà soignées à la main (en-US, fr-FR, de-DE, es-ES, ja, ko, zh-Hans) sont gardées telles quelles.
"""
import json, os

HERE = os.path.dirname(os.path.abspath(__file__))
EXISTING = ["en-US", "fr-FR", "de-DE", "es-ES", "ja", "ko", "zh-Hans"]

def bullets(items):
    return "\n".join("• " + i for i in items)

def desc(intro, middle, items, outro):
    parts = [intro]
    if middle:
        parts.append(middle)
    parts.append(bullets(items))
    parts.append(outro)
    return "\n\n".join(parts)

