# Quelle langue de texte pour quelle langue de l'App Store
LOCALE_TEXT = {
    "en-US": "en", "en-GB": "en", "en-AU": "en", "en-CA": "en",
    "fr-FR": "fr", "fr-CA": "fr", "es-ES": "es", "es-MX": "es",
    "de-DE": "de", "ja": "ja", "ko": "ko", "zh-Hans": "zh-Hans",
    "pt-BR": "pt-BR", "pt-PT": "pt-PT", "it": "it", "nl-NL": "nl-NL", "sv": "sv", "da": "da", "no": "no", "fi": "fi",
    "pl": "pl", "cs": "cs", "sk": "sk", "hu": "hu", "ro": "ro", "hr": "hr", "el": "el", "ru": "ru", "uk": "uk", "tr": "tr",
    "ar-SA": "ar-SA", "he": "he", "hi": "hi", "id": "id", "ms": "ms", "th": "th", "vi": "vi", "zh-Hant": "zh-Hant", "ca": "ca",
}

# Mots-clés en plus pour les variantes d'anglais (chaque pays a ses propres mots-clés : autant élargir).
EXTRA_KEYWORDS = {
    "foldly": {"en-AU": "iphone duo,fold counter,flip,hinge,habit tracker,digital detox,screen time,widgets,focus,wellbeing",
               "en-CA": "iphone duo,unfold,hinge counter,phone habit,detox,limit,streak,leaderboard,apple watch,widget"},
    "origamo": {"en-AU": "iphone duo,fold games,hinge,party,two player,face to face,board games,billiards,golf,quiz,family",
                "en-CA": "iphone duo,foldable games,hinge,party,multiplayer,duel,chess,checkers,air hockey,drawing,kids"},
    "waffle": {"en-AU": "waffle maker,cooking,chef,cafe,crepe,dessert,iphone duo,fold,restaurant game,cozy,food truck",
               "en-CA": "waffles,pancake,crepe,breakfast,cooking game,chef,diner,iphone duo,foldable,cozy,kitchen"},
}

def build(app, table, existing_skip):
    out = {"locales": {}, "skip": existing_skip}
    for loc, key in LOCALE_TEXT.items():
        if key not in table:
            continue
        name, sub, kw, promo, intro, middle, items, outro, whats = table[key]
        kw = EXTRA_KEYWORDS.get(app, {}).get(loc, kw)
        # 100 caractères max : on retire les derniers mots-clés si besoin
        parts = [k.strip() for k in kw.split(",") if k.strip()]
        while len(",".join(parts)) > 100: parts.pop()
        kw = ",".join(parts)
        entry = {"name": name, "subtitle": sub, "keywords": kw, "promo": promo, "description": desc(intro, middle, items, outro)}
        if whats:
            entry["whatsNew"] = whats
        for field, limit in (("name", 30), ("subtitle", 30), ("keywords", 100), ("promo", 170)):
            if len(entry[field]) > limit:
                raise SystemExit(f"{app} {loc} {field} trop long ({len(entry[field])}): {entry[field]}")
        out["locales"][loc] = entry
    return out

if __name__ == "__main__":
    for app, table, skip in (("foldly", FOLDLY, EXISTING), ("origamo", ORIGAMO, EXISTING), ("waffle", WAFFLE, [])):
        data = build(app, table, skip)
        with open(os.path.join(HERE, f"{app}.json"), "w") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        print(app, len(data["locales"]), "langues,", len([l for l in data["locales"] if l not in skip]), "à envoyer")
